<script>
    const vehicleSelect = document.getElementById('vr-vehiculo');
    const selectedVehicle = document.getElementById('vr-selected-vehicle');
    const vehicleCards = document.querySelectorAll('.vr-vehicle');
    const rangeStart = document.getElementById('vr-inicio');
    const rangeEnd = document.getElementById('vr-termino');
    function addMinutesToLocalDateTime(value, minutes) { const date = new Date(value); date.setMinutes(date.getMinutes() + minutes); const pad = (part) => String(part).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`; }
    function syncRangeEndMinimum() { if (!rangeStart || !rangeEnd || !rangeStart.value) return; const minimum = addMinutesToLocalDateTime(rangeStart.value, 1); rangeEnd.min = minimum; if (rangeEnd.value && rangeEnd.value <= rangeStart.value) rangeEnd.value = addMinutesToLocalDateTime(rangeStart.value, Number(rangeStart.dataset.defaultDuration || 60)); }
    rangeStart?.addEventListener('change', syncRangeEndMinimum);
    rangeStart?.addEventListener('input', syncRangeEndMinimum);
    syncRangeEndMinimum();
    function showSelectedVehicle() { const option = vehicleSelect?.selectedOptions?.[0]; if (selectedVehicle) selectedVehicle.textContent = option?.value ? option.textContent : 'Selecciona una tarjeta o el desplegable.'; vehicleCards.forEach((card) => card.classList.toggle('is-selected', card.dataset.vehicleId === vehicleSelect?.value)); }
    vehicleCards.forEach((card) => card.addEventListener('click', () => { if (!vehicleSelect) return; vehicleSelect.value = card.dataset.vehicleId; showSelectedVehicle(); document.getElementById('reservar')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }));
    vehicleSelect?.addEventListener('change', showSelectedVehicle); showSelectedVehicle();

    document.querySelectorAll('[data-destination-select]').forEach((select) => {
        const label = select.querySelector('[data-destination-label]');
        const checks = Array.from(select.querySelectorAll('[data-destination-check]'));
        const search = select.querySelector('[data-destination-search]');
        const options = Array.from(select.querySelectorAll('[data-destination-option]'));
        const syncLabel = () => {
            const selected = checks.filter((check) => check.checked).map((check) => check.closest('label')?.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean);
            if (label) label.textContent = selected.length ? `${selected.length} centro(s) seleccionado(s)` : 'Selecciona uno o mas centros';
        };
        checks.forEach((check) => check.addEventListener('change', syncLabel));
        search?.addEventListener('input', () => {
            const query = search.value.trim().toLocaleLowerCase('es');
            options.forEach((option) => { option.hidden = query !== '' && !option.innerText.toLocaleLowerCase('es').includes(query); });
        });
        syncLabel();
    });

    const actionPanels = document.querySelectorAll('.vr-action-panel');
    document.querySelectorAll('[data-reserva-toggle]').forEach((button) => button.addEventListener('click', () => {
        const panel = document.getElementById(button.dataset.reservaToggle);
        if (!panel) return;
        const wasHidden = panel.hidden;
        actionPanels.forEach((item) => { item.hidden = true; });
        panel.hidden = !wasHidden;
        if (wasHidden) panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }));
    document.querySelectorAll('[data-reserva-close]').forEach((button) => button.addEventListener('click', () => {
        const panel = document.getElementById(button.dataset.reservaClose);
        if (panel) panel.hidden = true;
    }));
    document.querySelectorAll('[data-eventualidad-form]').forEach((form) => {
        const type = form.querySelector('[data-eventualidad-type]');
        const returnField = form.querySelector('[data-eventualidad-return]');
        const returnInput = form.querySelector('[data-eventualidad-return-input]');
        const syncReturnRequirement = () => {
            const isDelay = type?.value === 'RETRASO_DEVOLUCION';
            if (returnField) returnField.hidden = !isDelay;
            if (returnInput) returnInput.required = isDelay;
        };
        type?.addEventListener('change', syncReturnRequirement);
        syncReturnRequirement();
    });
</script>
</body>
</html>
